-- Update last_message_at and log the inbound message.
UPDATE conversations SET last_message_at = NOW() WHERE conversation_id = $1::uuid;

UPDATE messages
SET conversation_id = $1::uuid, sender_type = 'lead'
WHERE msg_external_id = $2;

parameters.jsCode:
// Build the OpenRouter API request with property context + conversation history.
const trigger = $('When Called by WF1').first().json;
const propertyRow = $('Fetch Property Data').first().json;
const historyItems = $('Fetch Conversation History').all();

// Build property context from DB data or cache
let propData = {};
try {
  propData = typeof propertyRow.property_data === 'string'
    ? JSON.parse(propertyRow.property_data)
    : (propertyRow.property_data || {});
} catch(e) { propData = {}; }

// Merge direct columns with cache payload
const property = {
  title: propertyRow.title || propData.title || 'No disponible',
  price: propertyRow.price || propData.price || 'No disponible',
  currency: propertyRow.currency || propData.currency || 'MXN',
  location: propertyRow.location || propData.location || 'No disponible',
  property_type: propertyRow.property_type || propData.property_type || 'No especificado',
  operation_type: propertyRow.operation_type || propData.operation_type || 'No especificado',
  bedrooms: propertyRow.bedrooms || propData.bedrooms || 'No disponible',
  bathrooms: propertyRow.bathrooms || propData.bathrooms || 'No disponible',
  area_m2: propertyRow.area_m2 || propData.area_m2 || 'No disponible',
  description: propertyRow.description || propData.description || '',
  url: propertyRow.url || propData.url || ''
};

// System prompt
const systemPrompt = `You are a friendly, bilingual (Spanish/English) real estate assistant for a brokerage in Mexico City. You help potential buyers/renters learn about properties.

Current property:
- Title: ${property.title}
- Price: ${property.price} ${property.currency}
- Location: ${property.location}
- Type: ${property.property_type} (${property.operation_type})
- Bedrooms: ${property.bedrooms}
- Bathrooms: ${property.bathrooms}
- Area: ${property.area_m2} m2
- Description: ${property.description}
- Link: ${property.url}

Rules:
1. Answer using ONLY the property info above. Don't invent details.
2. If asked about info you don't have, say you'll check with the agent.
3. If the lead asks to schedule a visit, negotiate price, discuss financing, or anything that requires human judgment, start your response with [HANDOFF] and explain you'll connect them with an agent.
4. If the lead explicitly asks to talk to a human/agent, start your response with [HANDOFF].
5. Keep responses under 300 characters (WhatsApp readability).
6. Be warm, professional, concise.
7. Respond in the SAME LANGUAGE the lead uses (Spanish or English).
8. Never reveal you are an AI unless directly asked.`;

// Build conversation messages from history (reverse to chronological order)
const chatMessages = [{ role: 'system', content: systemPrompt }];

const history = historyItems
  .map(i => i.json)
  .filter(m => m.body && m.body.trim())
  .reverse(); // DB returns DESC, we need ASC

for (const msg of history) {
  if (msg.sender_type === 'lead') {
    chatMessages.push({ role: 'user', content: msg.body });
  } else if (msg.sender_type === 'ai') {
    chatMessages.push({ role: 'assistant', content: msg.body });
  }
  // Skip system/agent messages in LLM context
}

// Add the current message
chatMessages.push({ role: 'user', content: trigger.text });

return [{
  json: {
    chatMessages,
    conversation_id: trigger.conversation_id,
    phone: trigger.phone,
    assigned_agent_id: trigger.assigned_agent_id,
    current_property: trigger.current_property
  }
}];

// Parse LLM response and check for handoff triggers.
const llmResponse = $input.first().json;
const context = $('Build LLM Prompt').first().json;

let aiText = '';
try {
  aiText = llmResponse.choices[0].message.content || '';
} catch(e) {
  aiText = 'Lo siento, tuve un problema tecnico. Por favor intenta de nuevo.';
}

// Check for handoff trigger
const needsHandoff = aiText.startsWith('[HANDOFF]');

// Clean the handoff tag from the response
const cleanText = aiText.replace(/^\[HANDOFF\]\s*/i, '');

return [{
  json: {
    ai_response: cleanText,
    needs_handoff: needsHandoff,
    conversation_id: context.conversation_id,
    phone: context.phone,
    assigned_agent_id: context.assigned_agent_id,
    current_property: context.current_property
  }
}];
